rules:
@media (max-width: 900px) {
  .pkg-grid { grid-template-columns: 1fr; }
}

@media (min-width: 601px) and (max-width: 900px) {
  .pkg-grid { grid-template-columns: 1fr 1fr; }
}

@media (max-width: 760px) {
  .checkout-layout { grid-template-columns: 1fr; }
}

@media print {
  nav, .inv-actions, .footer-mini, .breadcrumb, .inv-breadcrumb { display: none !important; }
  .invoice-wrap { padding: 0px; }
  .invoice-card { box-shadow: none; border-radius: 0px; }
}

@keyframes spin-badge { 
  0% { transform: rotate(0deg); }
  100% { transform: rotate(360deg); }
}

@keyframes bob { 
  0%, 100% { transform: translateY(0px); }
  50% { transform: translateY(-12px); }
}

@keyframes marquee { 
  0% { transform: translateX(0px); }
  100% { transform: translateX(-50%); }
}

@keyframes heroCardIn { 
  0% { opacity: 0; transform: translateY(32px) scale(0.97); }
  100% { opacity: 1; transform: none; }
}

@media (max-width: 900px) {
  .home-baked { grid-template-columns: 1fr; }
  .home-baked-img { min-height: 260px; }
  .home-custom-banner { grid-template-columns: 1fr; }
  .home-custom-banner-visual { padding: 32px; }
  .home-footer-top { grid-template-columns: 1fr 1fr; gap: 2rem; }
}

@media (max-width: 600px) {
  .home-hero-card { padding: 36px 24px; margin: 0px 16px; }
  .home-hero-card h1 { font-size: 1.65rem; }
  .home-footer-top { grid-template-columns: 1fr; }
}

@keyframes fade-in { 
  0% { opacity: 0; transform: translateY(20px); }
  100% { opacity: 1; transform: translateY(0px); }
}

@media (max-width: 900px) {
  nav .nav-links { display: none; }
  .hero { grid-template-columns: 1fr; }
  .hero-right { min-height: 50vw; }
  .hero-left { padding: 3rem 6vw; }
  .features { grid-template-columns: 1fr; }
  .preview-grid { grid-template-columns: 1fr 1fr; }
  .about-strip { grid-template-columns: 1fr; gap: 3rem; }
  .t-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .custom-banner { grid-template-columns: 1fr; }
  .shop-wrapper { grid-template-columns: 1fr; }
  .sidebar { position: static; }
  .customize-page { grid-template-columns: 1fr; }
  .summary-panel { position: static; }
  .frosting-grid { grid-template-columns: 1fr 1fr 1fr; }
  .base-grid { grid-template-columns: 1fr; }
  .gallery-masonry { columns: 150px 2; }
  .controls-panel { flex-direction: column; align-items: stretch; bottom: 10px; left: 10px; right: 10px; gap: 8px; max-height: 50vh; }
  .cp-group { flex-direction: row; justify-content: space-between; align-items: center; }
  .topping-row { justify-content: space-between; }
}

@media (max-width: 760px) {
  .auth-wrap { grid-template-columns: 1fr; }
}

@media (max-width: 760px) {
  .auth-visual { display: none; }
}

@keyframes dtIn { 
  0% { opacity: 0; transform: scale(0.94) translateY(12px); }
  100% { opacity: 1; transform: none; }
}

@media (max-width: 560px) {
  .dt-modal-body { grid-template-columns: 1fr; }
}
